-- 確認
SELECT flow_key, status, version, timeout_ms, updated_at FROM web_automation_flows_v2 WHERE app_key='hug-banso-navi' AND flow_key IN (
  'ai_deepseek_prompt_send',
  'ai_chatgpt_prompt_send',
  'ai_gemini_prompt_send',
  'ai_ollama_prompt_send',
  'ai_openrouter_prompt_send',
  'ai_laravel_prompt_send'
) ORDER BY flow_key;

SELECT fl.flow_key, f.file_path, f.is_active, f.content_hash FROM web_automation_files_v2 f INNER JOIN web_automation_flows_v2 fl ON fl.id=f.flow_id WHERE fl.app_key='hug-banso-navi' AND fl.flow_key IN (
  'ai_deepseek_prompt_send',
  'ai_chatgpt_prompt_send',
  'ai_gemini_prompt_send',
  'ai_ollama_prompt_send',
  'ai_openrouter_prompt_send',
  'ai_laravel_prompt_send'
) ORDER BY fl.flow_key, f.file_path;
